import './style.css'

type Support = 'Both' | 'Arduino' | 'ESP32'
type FunctionEntry = { kind: 'function'; name: string; group: string; summary: string; syntax: string; parameters: string; returns: string; example: string; behavior: string; tips: string; mistakes: string; support: Support }
type ComponentFunction = { name: string; explanation: string; syntax: string; example: string }
type ComponentEntry = { kind: 'component'; name: string; group: string; summary: string; whatItDoes: string; pins: string; connection: string; specs: string; tips: string; mistakes: string; support: Support; visual: string; functions?: ComponentFunction[] }
type WikiItem = FunctionEntry | ComponentEntry
type QuizQuestion = { prompt: string; choices: string[]; answer: number; explanation: string; topic: string }

const functions: FunctionEntry[] = [
  { kind: 'function', name: 'pinMode()', group: 'Digital I/O', summary: 'Tell a pin whether it should listen for information or control something.', syntax: 'pinMode(pin, mode);', parameters: '<strong>pin</strong> is the pin number. <strong>mode</strong> is INPUT, OUTPUT, or INPUT_PULLUP.', returns: 'Nothing. It sets the pin up for later use.', example: 'pinMode(13, OUTPUT);', behavior: 'Pin 13 is now ready to control a light or another output.', tips: 'Set a pin mode in setup() before using the pin.', mistakes: 'Forgetting pinMode() can make a pin behave unpredictably.', support: 'Both' },
  { kind: 'function', name: 'digitalWrite()', group: 'Digital I/O', summary: 'Turn a digital output on or off.', syntax: 'digitalWrite(pin, value);', parameters: '<strong>pin</strong> is the output pin. <strong>value</strong> is HIGH (on) or LOW (off).', returns: 'Nothing.', example: 'digitalWrite(13, HIGH);', behavior: 'The device connected to pin 13 receives a HIGH signal.', tips: 'Use it after setting the pin to OUTPUT.', mistakes: 'Writing HIGH to an INPUT pin does not control a component.', support: 'Both' },
  { kind: 'function', name: 'digitalRead()', group: 'Digital I/O', summary: 'Check whether a digital input is HIGH or LOW.', syntax: 'digitalRead(pin);', parameters: '<strong>pin</strong> is the input pin you want to check.', returns: 'HIGH or LOW.', example: 'int pressed = digitalRead(7);', behavior: 'pressed becomes HIGH when the input signal is on.', tips: 'Use INPUT_PULLUP for a button when you want a built-in pull-up resistor.', mistakes: 'A floating input can randomly change between HIGH and LOW.', support: 'Both' },
  { kind: 'function', name: 'analogRead()', group: 'Analog I/O', summary: 'Measure a changing voltage, such as a knob or light sensor.', syntax: 'analogRead(pin);', parameters: '<strong>pin</strong> is an analog-capable pin, like A0 on many Arduino boards.', returns: 'A number representing the voltage. Arduino Uno usually returns 0-1023; ESP32 usually returns 0-4095.', example: 'int light = analogRead(A0);', behavior: 'light contains a number that changes as the sensor voltage changes.', tips: 'Check your board pinout: ESP32 ADC pins are not all interchangeable.', mistakes: 'Do not assume ESP32 and Uno use the same analog range.', support: 'Both' },
  { kind: 'function', name: 'analogWrite()', group: 'Analog I/O', summary: 'Create a PWM signal that can dim an LED or control motor speed.', syntax: 'analogWrite(pin, value);', parameters: '<strong>pin</strong> is PWM-capable. <strong>value</strong> is usually 0 (off) to 255 (full power).', returns: 'Nothing.', example: 'analogWrite(9, 128);', behavior: 'A PWM LED on pin 9 appears about half as bright.', tips: 'On ESP32, ledcWrite() is commonly used for more control over PWM.', mistakes: 'PWM is not a smooth analog voltage; it switches quickly on and off.', support: 'Both' },
  { kind: 'function', name: 'delay()', group: 'Timing', summary: 'Pause the program for a set number of milliseconds.', syntax: 'delay(milliseconds);', parameters: '<strong>milliseconds</strong> is the pause length. 1000 milliseconds equals 1 second.', returns: 'Nothing.', example: 'delay(500);', behavior: 'The board waits for half a second before continuing.', tips: 'Short delays are fine for simple timing and learning.', mistakes: 'Long delays stop other code from running during the wait.', support: 'Both' },
  { kind: 'function', name: 'millis()', group: 'Timing', summary: 'Find out how many milliseconds have passed since the board started.', syntax: 'millis();', parameters: 'No parameters.', returns: 'An unsigned long time value in milliseconds.', example: 'unsigned long now = millis();', behavior: 'now stores the board uptime without pausing the program.', tips: 'Use millis() for timers that need to keep checking inputs.', mistakes: 'Store the result in unsigned long, not int.', support: 'Both' },
  { kind: 'function', name: 'map()', group: 'Math', summary: 'Convert a number from one range into another range.', syntax: 'map(value, fromLow, fromHigh, toLow, toHigh);', parameters: '<strong>value</strong> is the number to convert. The other values define the old and new ranges.', returns: 'The converted long integer.', example: 'int brightness = map(sensor, 0, 1023, 0, 255);', behavior: 'A sensor reading of 512 becomes about 127.', tips: 'map() does not automatically limit values outside the input range.', mistakes: 'Use constrain() when values must stay inside a safe range.', support: 'Both' },
  { kind: 'function', name: 'constrain()', group: 'Math', summary: 'Keep a number between a minimum and maximum.', syntax: 'constrain(value, min, max);', parameters: '<strong>value</strong> is checked against <strong>min</strong> and <strong>max</strong>.', returns: 'The original value, min, or max.', example: 'speed = constrain(speed, 0, 255);', behavior: 'Values below 0 become 0, and values above 255 become 255.', tips: 'It is useful for making user input safe before sending it to hardware.', mistakes: 'Remember to save the returned result back into a variable.', support: 'Both' },
  { kind: 'function', name: 'Serial.begin()', group: 'Serial Communication', summary: 'Start the serial connection used to talk to your computer.', syntax: 'Serial.begin(baudRate);', parameters: '<strong>baudRate</strong> is the communication speed, commonly 9600 or 115200.', returns: 'Nothing.', example: 'Serial.begin(115200);', behavior: 'The board opens a serial connection at 115200 baud.', tips: 'Choose the same baud rate in the Serial Monitor.', mistakes: 'A mismatched baud rate makes messages look like random symbols.', support: 'Both' },
  { kind: 'function', name: 'Serial.print()', group: 'Serial Communication', summary: 'Send text or a value to the Serial Monitor without a new line.', syntax: 'Serial.print(value);', parameters: '<strong>value</strong> can be text, a number, or a variable.', returns: 'Nothing.', example: 'Serial.print("Temperature: ");', behavior: 'The next message appears on the same line.', tips: 'Use Serial.print() to build a line piece by piece.', mistakes: 'Start Serial.begin() before trying to print.', support: 'Both' },
  { kind: 'function', name: 'Serial.println()', group: 'Serial Communication', summary: 'Send text or a value to the Serial Monitor and start a new line.', syntax: 'Serial.println(value);', parameters: '<strong>value</strong> can be text, a number, or a variable.', returns: 'Nothing.', example: 'Serial.println(analogRead(A0));', behavior: 'The reading appears and the cursor moves to the next line.', tips: 'It is handy for readable debugging output.', mistakes: 'Too many prints in a fast loop can make the monitor hard to read.', support: 'Both' },
  { kind: 'function', name: 'if / else', group: 'Control Structures', summary: 'Choose what code runs based on whether a condition is true.', syntax: 'if (condition) { ... } else { ... }', parameters: '<strong>condition</strong> is a comparison such as button == HIGH.', returns: 'Nothing; it chooses a code path.', example: 'if (button == HIGH) {\n  digitalWrite(13, HIGH);\n} else {\n  digitalWrite(13, LOW);\n}', behavior: 'The LED follows the button state.', tips: 'Use == to compare. A single = changes a value.', mistakes: 'Leaving out braces can make the wrong lines conditional.', support: 'Both' },
  { kind: 'function', name: 'for', group: 'Control Structures', summary: 'Repeat a block of code a known number of times.', syntax: 'for (start; condition; step) { ... }', parameters: '<strong>start</strong> runs once, <strong>condition</strong> is checked each time, and <strong>step</strong> updates the counter.', returns: 'Nothing; it repeats code.', example: 'for (int pin = 2; pin <= 5; pin++) {\n  digitalWrite(pin, HIGH);\n}', behavior: 'Pins 2 through 5 are turned on one by one.', tips: 'Use pin++ to increase a counter by one.', mistakes: 'A wrong condition can create an endless loop.', support: 'Both' },
  { kind: 'function', name: 'while', group: 'Control Structures', summary: 'Repeat code as long as a condition stays true.', syntax: 'while (condition) { ... }', parameters: '<strong>condition</strong> is checked before every repetition.', returns: 'Nothing; it repeats until false.', example: 'while (digitalRead(7) == LOW) {\n  Serial.println("Waiting");\n}', behavior: 'The message repeats while the input remains LOW.', tips: 'Make sure something inside the loop can change the condition.', mistakes: 'A condition that never changes can lock up the board.', support: 'Both' },
  { kind: 'function', name: 'switch', group: 'Control Structures', summary: 'Pick one action from several possible values.', syntax: 'switch (value) { case 1: ... break; }', parameters: '<strong>value</strong> is checked against each case label.', returns: 'Nothing; it selects a matching case.', example: 'switch (mode) {\n  case 1:\n    Serial.println("Low");\n    break;\n}', behavior: 'The matching case runs once.', tips: 'Add break to stop the next case from running too.', mistakes: 'Forgetting break can make multiple cases execute.', support: 'Both' },
]

const components: ComponentEntry[] = [
  { kind: 'component', name: 'LED', group: 'Basic Components', summary: 'A tiny light that turns electrical energy into visible light.', whatItDoes: 'An LED glows when current flows through it in the correct direction.', pins: 'Long leg: anode (+). Short leg: cathode (-).', connection: 'Connect the long leg to a GPIO through a resistor and the short leg to GND.', specs: 'Typical forward voltage: 1.8-3.3V. Always use a current-limiting resistor.', tips: 'The flat edge on the body usually marks the cathode side.', mistakes: 'Connecting an LED directly to a pin can damage both the LED and the board.', support: 'Both', visual: 'led' },
  { kind: 'component', name: 'Resistor', group: 'Basic Components', summary: 'A component that limits how much current can flow.', whatItDoes: 'It protects LEDs and lets you create simple voltage dividers.', pins: 'Two leads; resistors are not polarized, so either direction works.', connection: 'Place it in series with an LED, or between a signal and ground for a pull-down.', specs: 'Resistance is measured in ohms (Ω). Common LED values are 220Ω to 1kΩ.', tips: 'Read the colored bands or use a multimeter to identify its value.', mistakes: 'A resistor in the wrong place may not protect the component you intended.', support: 'Both', visual: 'resistor' },
  { kind: 'component', name: 'Potentiometer', group: 'Basic Components', summary: 'A knob that acts like an adjustable voltage divider.', whatItDoes: 'Turning the knob changes the voltage at its middle pin.', pins: 'Outer pins go to power and GND. Middle pin is the wiper output.', connection: 'Connect outer pins to 3.3V/GND and the middle pin to an analog input.', specs: 'Common values: 10kΩ. ESP32 inputs should stay within their voltage limits.', tips: 'Swap the outer pins if you want the knob direction reversed.', mistakes: 'Leaving the middle pin disconnected gives you no usable reading.', support: 'Both', visual: 'knob' },
  { kind: 'component', name: 'Push Button', group: 'Basic Components', summary: 'A simple switch that connects two points while pressed.', whatItDoes: 'It lets a person provide a digital HIGH or LOW signal.', pins: 'Opposite legs are connected internally; pressing joins the two sides.', connection: 'Use INPUT_PULLUP with one side on a pin and one side on GND.', specs: 'Mechanical buttons can bounce, causing several quick readings.', tips: 'Rotate four-leg buttons across the breadboard center gap.', mistakes: 'Using the wrong legs or leaving an input floating causes unreliable results.', support: 'Both', visual: 'button' },
  { kind: 'component', name: 'Buzzer', group: 'Basic Components', summary: 'A small part that makes a beep when driven with a signal.', whatItDoes: 'An active buzzer beeps with power; a passive buzzer needs a changing tone signal.', pins: 'Usually + and -. Follow the polarity markings.', connection: 'Connect + to a suitable output through a transistor when current is high; connect - to GND.', specs: 'Check its operating voltage and current before powering it.', tips: 'Use tone() on many Arduino boards, or PWM on ESP32.', mistakes: 'Driving a larger buzzer directly from a GPIO can overload the pin.', support: 'Both', visual: 'buzzer' },
  { kind: 'component', name: 'Servo Motor', group: 'Motors', summary: 'A motor that moves to a requested angle.', whatItDoes: 'A servo combines a motor and controller to hold a position.', pins: 'Brown/black: GND. Red: power. Orange/yellow: signal.', connection: 'Connect signal to a PWM-capable pin and share GND with the board.', specs: 'Many servos need a separate 5V supply because startup current is high.', tips: 'Power the servo separately for steadier behavior.', mistakes: 'Never assume a board USB port can power several servos.', support: 'Both', visual: 'servo' },
  { kind: 'component', name: 'HC-SR04 Ultrasonic Sensor', group: 'Sensors', summary: 'A distance sensor that measures echoes of a sound pulse.', whatItDoes: 'TRIG starts a pulse and ECHO reports how long the sound takes to return.', pins: 'VCC, TRIG, ECHO, GND.', connection: 'Connect TRIG and ECHO to digital pins. Use a voltage divider for ESP32 ECHO.', specs: 'Typical range: about 2-400 cm. It commonly expects 5V power.', tips: 'Aim it at a flat surface for a steadier reading.', mistakes: 'The 5V ECHO signal can damage a 3.3V-only ESP32 input.', support: 'Both', visual: 'ultrasonic' },
  { kind: 'component', name: 'DHT11 / DHT22', group: 'Sensors', summary: 'A simple digital sensor for temperature and humidity.', whatItDoes: 'It sends temperature and relative humidity readings over one data pin.', pins: 'VCC, DATA, and GND. Some modules include a pull-up resistor.', connection: 'Connect DATA to a digital pin and add a 10kΩ pull-up if the bare sensor needs one.', specs: 'DHT22 is more accurate and has a wider range than DHT11.', tips: 'Read it no faster than the sensor datasheet allows.', mistakes: 'A missing pull-up resistor or incorrect library setup often causes NaN readings.', support: 'Both', visual: 'sensor' },
  { kind: 'component', name: 'OLED Display', group: 'Displays', summary: 'A small, high-contrast screen that can show text and graphics.', whatItDoes: 'It receives drawing commands over I2C or SPI and lights individual pixels.', pins: 'I2C modules usually have VCC, GND, SDA, and SCL.', connection: 'Connect SDA/SCL to the board pins listed in its pinout and share GND.', specs: 'Common sizes are 0.96 inch and 1.3 inch at 128x64 pixels.', tips: 'The I2C address is often 0x3C or 0x3D.', mistakes: 'Using the wrong address makes a working display look blank.', support: 'Both', visual: 'oled' },
  { kind: 'component', name: 'Relay Module', group: 'Modules', summary: 'An electrically controlled switch for higher-power loads.', whatItDoes: 'A coil moves contacts so a low-voltage GPIO can control another circuit.', pins: 'Usually VCC, GND, and IN; screw terminals are COM, NO, and NC.', connection: 'Connect the control side to the board, and wire the load side separately and safely.', specs: 'Check contact voltage/current ratings and whether the module is active LOW.', tips: 'Treat mains voltage as hazardous and use proper enclosures.', mistakes: 'Do not power the relay coil from a weak GPIO pin.', support: 'Both', visual: 'relay' },
  { kind: 'component', name: 'DC Motor', group: 'Motors', summary: 'A motor that spins continuously when powered.', whatItDoes: 'It converts electrical energy into rotation for wheels, fans, and mechanisms.', pins: 'Two motor wires: reversing them reverses the spin direction.', connection: 'Use a motor driver or transistor, an external supply, and a shared ground.', specs: 'Motors can draw much more current at startup than while spinning.', tips: 'Add a flyback diode when using a transistor driver.', mistakes: 'Never power a motor directly from a GPIO pin.', support: 'Both', visual: 'motor' },
  { kind: 'component', name: '28BYJ-48 Stepper Motor', group: 'Motors', summary: 'A geared motor that moves in small, precise steps.', whatItDoes: 'It turns a set number of steps instead of simply spinning freely.', pins: 'The common version uses a 5-wire connector that plugs into its driver board.', connection: 'Connect it to a ULN2003 driver board, then connect the driver inputs to GPIO pins.', specs: 'The 5V version is common and has a high gear reduction for slow movement.', tips: 'Use a stepper library to handle the coil sequence.', mistakes: 'The motor needs the driver board; connecting coils straight to a GPIO is unsafe.', support: 'Both', visual: 'stepper' },
  { kind: 'component', name: 'ULN2003 Driver', group: 'Modules', summary: 'A driver board that lets a microcontroller control larger coils or motors.', whatItDoes: 'Its transistor array switches current for loads such as the 28BYJ-48.', pins: 'IN1-IN4 are control inputs; OUT1-OUT4 drive the motor; VCC and GND power it.', connection: 'Plug the stepper into the socket and connect four input pins to GPIOs.', specs: 'It is a low-side transistor driver, not a smart motor controller.', tips: 'Connect grounds together so the control signals have a reference.', mistakes: 'The board cannot decide the step sequence for you.', support: 'Both', visual: 'driver' },
  { kind: 'component', name: 'PIR Sensor', group: 'Sensors', summary: 'A motion sensor that notices changes in infrared heat.', whatItDoes: 'It outputs a digital signal when a warm body moves across its view.', pins: 'VCC, OUT, and GND.', connection: 'Power it, connect OUT to a digital input, and share GND.', specs: 'Most modules have adjustable sensitivity and hold-time knobs.', tips: 'Give it a short warm-up period after powering on.', mistakes: 'It detects motion, not a person who is standing perfectly still.', support: 'Both', visual: 'pir' },
  { kind: 'component', name: 'LDR', group: 'Sensors', summary: 'A light-dependent resistor whose resistance changes with brightness.', whatItDoes: 'It forms a voltage divider that an analog pin can measure.', pins: 'Two leads; it is not polarized.', connection: 'Pair it with a fixed resistor between power and ground, then read the middle point.', specs: 'Readings depend on the fixed resistor and the surrounding light.', tips: 'Shield it from stray light when you need consistent readings.', mistakes: 'An LDR alone is not an analog voltage source.', support: 'Both', visual: 'ldr' },
  { kind: 'component', name: 'Joystick Module', group: 'Modules', summary: 'Two potentiometers and a push button in one small control.', whatItDoes: 'It reports left/right, up/down, and button press signals.', pins: 'VCC, GND, VRx, VRy, and SW.', connection: 'Connect VRx and VRy to analog pins, SW to a digital pin, and share power/ground.', specs: 'The resting analog values are usually near the middle of the ADC range.', tips: 'Calibrate the center value instead of assuming it is exact.', mistakes: 'Swapping axes changes which direction your code sees.', support: 'Both', visual: 'joystick' },
  { kind: 'component', name: 'LCD Display', group: 'Displays', summary: 'A character screen for showing readable text.', whatItDoes: 'It displays letters and numbers, often in 16 columns by 2 rows.', pins: 'Parallel versions have many pins; I2C backpacks usually expose VCC, GND, SDA, and SCL.', connection: 'Use an I2C backpack when possible to save GPIO pins.', specs: 'The contrast knob controls whether characters are visible.', tips: 'The common I2C address is often 0x27 or 0x3F.', mistakes: 'A powered LCD with no contrast adjustment can look blank.', support: 'Both', visual: 'lcd' },
  { kind: 'component', name: 'IR Receiver', group: 'Communication', summary: 'A sensor that receives commands from infrared remote controls.', whatItDoes: 'It turns a remote’s invisible flashes into digital signal pulses.', pins: 'VCC, OUT, and GND.', connection: 'Connect OUT to a digital input and point the receiver at the remote.', specs: 'It commonly receives around 38 kHz IR signals.', tips: 'Use a library to decode different remote protocols.', mistakes: 'Bright sunlight can interfere with infrared reception.', support: 'Both', visual: 'ir' },
  { kind: 'component', name: 'RGB LED', group: 'Basic Components', summary: 'Three LEDs in one package for mixing red, green, and blue light.', whatItDoes: 'Changing the brightness of each color creates many visible colors.', pins: 'Red, green, blue, and a shared common anode or cathode pin.', connection: 'Use one resistor per color channel and three PWM-capable pins.', specs: 'Common-anode and common-cathode versions use opposite logic.', tips: 'Start with low brightness while testing the color channels.', mistakes: 'One shared resistor can make mixed colors unevenly bright.', support: 'Both', visual: 'rgb' },
  { kind: 'component', name: 'Breadboard', group: 'Basic Components', summary: 'A reusable board for making temporary connections without soldering.', whatItDoes: 'Hidden metal clips connect groups of holes under the plastic surface.', pins: 'No electronic pins; the power rails and connected rows are the important areas.', connection: 'Place components across the center gap and use rails for power and ground.', specs: 'Rows are commonly connected in groups of five, with a break between halves.', tips: 'Use short jumper wires and keep power rails consistent.', mistakes: 'Assuming every hole is connected can create silent wiring errors.', support: 'Both', visual: 'breadboard' },
]

const componentExamples: Record<string, { code: string; explanation: string }> = {
  LED: { code: 'int ledPin = 13;\n\nvoid setup() {\n  pinMode(ledPin, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(ledPin, HIGH);\n  delay(1000);\n  digitalWrite(ledPin, LOW);\n  delay(1000);\n}', explanation: 'pinMode() prepares the LED pin. digitalWrite() turns the LED on and off, with delay() making the blink easy to see.' },
  Resistor: { code: 'const int ledPin = 13;\n\nvoid setup() {\n  pinMode(ledPin, OUTPUT);\n}\n\nvoid loop() {\n  analogWrite(ledPin, 80);\n}', explanation: 'The resistor sits in series with the LED to limit current. The code uses PWM to keep the light dim.' },
  Potentiometer: { code: 'const int knobPin = A0;\n\nvoid setup() {\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int value = analogRead(knobPin);\n  Serial.println(value);\n  delay(100);\n}', explanation: 'The middle potentiometer pin goes to A0. Turning the knob changes the analog reading printed to the Serial Monitor.' },
  'Push Button': { code: 'const int buttonPin = 7;\n\nvoid setup() {\n  pinMode(buttonPin, INPUT_PULLUP);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  if (digitalRead(buttonPin) == LOW) {\n    Serial.println("Pressed");\n  }\n}', explanation: 'INPUT_PULLUP keeps the input stable. With this wiring, pressing the button connects the pin to ground, so the reading becomes LOW.' },
  Buzzer: { code: 'const int buzzerPin = 8;\n\nvoid setup() {\n  pinMode(buzzerPin, OUTPUT);\n}\n\nvoid loop() {\n  tone(buzzerPin, 440);\n  delay(500);\n  noTone(buzzerPin);\n  delay(500);\n}', explanation: 'tone() makes a passive buzzer vibrate at 440 Hz. noTone() stops it after half a second.' },
  'Servo Motor': { code: '#include <Servo.h>\nServo arm;\n\nvoid setup() {\n  arm.attach(9);\n}\n\nvoid loop() {\n  arm.write(90);\n  delay(1000);\n}', explanation: 'attach() connects the servo signal wire to a pin. write(90) asks the servo to move to its center angle.' },
  'HC-SR04 Ultrasonic Sensor': { code: 'const int trigPin = 5;\nconst int echoPin = 6;\n\nvoid setup() {\n  pinMode(trigPin, OUTPUT);\n  pinMode(echoPin, INPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  digitalWrite(trigPin, HIGH);\n  delayMicroseconds(10);\n  digitalWrite(trigPin, LOW);\n  long time = pulseIn(echoPin, HIGH);\n  Serial.println(time / 58);\n}', explanation: 'The trigger pin sends a short pulse. The echo time is converted to an approximate distance in centimeters.' },
  'DHT11 / DHT22': { code: '#include <DHT.h>\nDHT sensor(2, DHT22);\n\nvoid setup() {\n  Serial.begin(9600);\n  sensor.begin();\n}\n\nvoid loop() {\n  Serial.println(sensor.readTemperature());\n  delay(2000);\n}', explanation: 'The DHT library asks the sensor for a temperature reading. DHT11 and DHT22 use the same basic pattern.' },
  'OLED Display': { code: '#include <Adafruit_SSD1306.h>\nAdafruit_SSD1306 display(128, 64);\n\nvoid setup() {\n  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);\n  display.println("Hello board");\n  display.display();\n}\n\nvoid loop() {}', explanation: 'The display is addressed over I2C. Text is drawn into memory first, then display() sends it to the screen.' },
  'Relay Module': { code: 'const int relayPin = 4;\n\nvoid setup() {\n  pinMode(relayPin, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(relayPin, LOW);\n  delay(1000);\n  digitalWrite(relayPin, HIGH);\n  delay(1000);\n}', explanation: 'The GPIO controls the relay input. This example assumes an active-LOW module; check your board before connecting a load.' },
  'DC Motor': { code: 'const int motorPin = 9;\n\nvoid setup() {\n  pinMode(motorPin, OUTPUT);\n}\n\nvoid loop() {\n  analogWrite(motorPin, 180);\n}', explanation: 'A motor driver receives the PWM signal, not the motor itself. The value 180 sets a medium speed.' },
  '28BYJ-48 Stepper Motor': { code: '#include <Stepper.h>\nStepper motor(2048, 8, 10, 9, 11);\n\nvoid setup() {\n  motor.setSpeed(10);\n}\n\nvoid loop() {\n  motor.step(2048);\n}', explanation: 'The library sequences the four driver inputs. One 2048-step turn is a useful starting point for this geared motor.' },
  'ULN2003 Driver': { code: 'const int input1 = 8;\n\nvoid setup() {\n  pinMode(input1, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(input1, HIGH);\n  delay(500);\n  digitalWrite(input1, LOW);\n}', explanation: 'The ULN2003 receives a small GPIO signal at an input and switches a larger current at its matching output.' },
  'PIR Sensor': { code: 'const int motionPin = 2;\n\nvoid setup() {\n  pinMode(motionPin, INPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  if (digitalRead(motionPin) == HIGH) {\n    Serial.println("Motion");\n  }\n}', explanation: 'The PIR output becomes HIGH when it senses movement. The code prints a message each time motion is detected.' },
  LDR: { code: 'const int lightPin = A0;\n\nvoid setup() {\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int brightness = analogRead(lightPin);\n  Serial.println(brightness);\n  delay(200);\n}', explanation: 'The LDR and a fixed resistor form a voltage divider. analogRead() turns the changing light level into a number.' },
  'Joystick Module': { code: 'const int xPin = A0;\nconst int yPin = A1;\n\nvoid setup() {\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  Serial.print(analogRead(xPin));\n  Serial.print(", ");\n  Serial.println(analogRead(yPin));\n}', explanation: 'The two potentiometers inside the joystick provide separate X and Y analog readings.' },
  'LCD Display': { code: '#include <LiquidCrystal_I2C.h>\nLiquidCrystal_I2C lcd(0x27, 16, 2);\n\nvoid setup() {\n  lcd.init();\n  lcd.backlight();\n  lcd.print("Hello board");\n}\n\nvoid loop() {}', explanation: 'The I2C LCD uses only two data wires. init() starts it and print() writes a message to the character display.' },
  'IR Receiver': { code: '#include <IRremote.hpp>\n\nvoid setup() {\n  Serial.begin(9600);\n  IrReceiver.begin(2);\n}\n\nvoid loop() {\n  if (IrReceiver.decode()) {\n    Serial.println(IrReceiver.decodedIRData.command);\n    IrReceiver.resume();\n  }\n}', explanation: 'The library decodes the remote pulse pattern. Each received command is printed, which helps identify remote buttons.' },
  'RGB LED': { code: 'const int red = 9;\nconst int green = 10;\nconst int blue = 11;\n\nvoid setup() {\n  analogWrite(red, 255);\n  analogWrite(green, 80);\n  analogWrite(blue, 0);\n}\n\nvoid loop() {}', explanation: 'Each color leg gets its own PWM value and resistor. Mixing the three values creates the final color.' },
  Breadboard: { code: 'const int ledPin = 13;\n\nvoid setup() {\n  pinMode(ledPin, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(ledPin, HIGH);\n}', explanation: 'The breadboard is the physical connection surface. The code stays simple because the board handles the temporary wiring.' },
}

const componentFunction = (name: string, explanation: string, syntax: string, example: string): ComponentFunction => ({ name, explanation, syntax, example })
