function makeFunction([name, group, summary, support]: [string, string, string, Support]): FunctionEntry { const bare = name.replace(/[()]/g, ''); return { kind: 'function', name, group, summary, syntax: `${name.includes('(') ? name : `${name}()`}(value);`, parameters: '<strong>value</strong> is the input or setting used by this reference item.', returns: `A result related to ${bare}, or nothing when it changes hardware.`, example: `${name.includes('(') ? name : `${name}()`}(value);`, behavior: `The board performs the ${bare} operation once the code runs.`, tips: 'Start with a small value and check your board pinout or library documentation.', mistakes: 'Use the correct board support and make sure the required library is installed.', support } }
function makeComponent([name, group, summary, support, visual]: [string, string, string, Support, string]): ComponentEntry { return { kind: 'component', name, group, summary, whatItDoes: summary, pins: 'Power, ground, and one or more signal pins. Check the label on your exact module.', connection: 'Connect power and ground first, then connect the signal pin to a suitable GPIO or bus pin.', specs: 'Typical voltage depends on the module. Check its datasheet before connecting power or a load.', tips: 'Look for the module pin labels and share ground with the Arduino or ESP32.', mistakes: 'Do not connect a higher-voltage signal directly to an ESP32 input.', support, visual } }

functions.push(...functionCatalog.map(makeFunction).filter((item) => !functions.some((existing) => existing.name === item.name)))
components.push(...componentCatalog.map(makeComponent).filter((item) => !components.some((existing) => existing.name === item.name)))
components.forEach((item) => { item.functions = componentFunctionSets[item.name] || defaultComponentFunctions(item) })

