const quizNames = Object.keys(quizQuestions)

const app = document.querySelector<HTMLDivElement>('#app')!
let activeKind: 'home' | 'functions' | 'components' | 'quiz' | 'socials' = 'home'
let selected: WikiItem | null = null
let query = ''
let lightMode = false
let boardFilter: Support | 'All' = 'All'
let categoryFilter = 'All'
let showFavorites = false
let favorites = new Set<string>(JSON.parse(localStorage.getItem('ardwiki-favorites') || '[]'))
let recent: string[] = JSON.parse(localStorage.getItem('ardwiki-recent') || '[]')
let quizCategory = 'Beginner'
let quizRound: QuizQuestion[] = []
let quizIndex = 0
let quizScore = 0
let quizAnswer: number | null = null
let quizBest: Record<string, number> = JSON.parse(localStorage.getItem('circuitkid-quiz-best') || '{}')
type GitHubRepo = { name: string; html_url: string; description: string | null; language: string | null; stargazers_count: number; forks_count: number; updated_at: string }
let githubRepos: GitHubRepo[] | null = null
let githubLoading = false
let githubError = false
const allItems = [...functions, ...components]
const supportClass = (support: Support) => support.toLowerCase()

function render() {
  if (selected) { recent = [selected.name, ...recent.filter((name) => name !== selected?.name)].slice(0, 5); localStorage.setItem('ardwiki-recent', JSON.stringify(recent)) }
  const filtered = allItems.filter((item) => `${item.name} ${item.summary} ${item.group}`.toLowerCase().includes(query.toLowerCase()) && (boardFilter === 'All' || item.support === boardFilter || item.support === 'Both') && (categoryFilter === 'All' || item.group === categoryFilter))
  const visible = showFavorites ? filtered.filter((item) => favorites.has(item.name)) : query ? filtered : activeKind === 'functions' ? functions : activeKind === 'components' ? components : allItems.slice(0, 6)
  app.innerHTML = `<div class="app-shell ${lightMode ? 'light' : ''}"><header class="topbar"><a class="brand" href="#" data-action="home"><span class="brand-mark">⌁</span><span>Ard<span class="brand-accent">Wiki</span></span><small>Arduino & ESP32 Knowledge Base</small></a><div class="topbar-actions"><button class="icon-button" data-action="theme" aria-label="Toggle light mode">${lightMode ? '☼' : '◐'}</button><button class="random-button" data-action="random" aria-label="Open a random topic">✦ Random topic</button><a class="github-link" href="https://github.com/arduino" target="_blank" rel="noreferrer">↗ Arduino community</a></div></header><div class="layout"><aside class="sidebar"><div class="mobile-close"><button class="icon-button" data-action="close-menu" aria-label="Close navigation">×</button></div><div class="sidebar-label">Explore</div>${navButton('home', '⌂', 'Home')}${navButton('functions', 'ƒ', 'Functions', `${functions.length} entries`)}${navButton('components', '◈', 'Components', `${components.length} entries`)}${navButton('quiz', '✓', 'Quiz', `${quizNames.length} topics`)}${navButton('socials', '↗', 'Socials', 'CircuitKid')}<button class="nav-item" data-action="favorites"><span class="nav-icon">☆</span><span>Favorites</span><small>${favorites.size}</small></button><div class="sidebar-divider"></div><div class="sidebar-label">Quick start</div>${recent.length ? `<div class="recent-label">Recently viewed</div>${recent.slice(0, 3).map((name) => `<button class="recent-item" data-action="open-recent" data-name="${name}">${name}</button>`).join('')}` : ''}<a class="sidebar-tip" href="#" data-action="open-function" data-name="pinMode()"><span class="tip-icon">01</span><span><strong>Start with pins</strong><small>pinMode() and digitalWrite()</small></span></a><a class="sidebar-tip" href="#" data-action="open-component" data-name="LED"><span class="tip-icon orange">✦</span><span><strong>Meet your first parts</strong><small>LEDs, resistors, buttons</small></span></a><div class="sidebar-footer"><span class="status-dot"></span> Reference updated<br><strong>September 2026</strong><div class="creator-credit">CircuitKid / Creator<br><a href="https://github.com/circuitkidyt" target="_blank" rel="noreferrer">GitHub</a><span>·</span><a href="https://tiktok.com/@circuitkid" target="_blank" rel="noreferrer">TikTok</a></div></div></aside><main class="main-content"><div class="mobile-nav"><button class="menu-button" data-action="open-menu">☰ <span>Menu</span></button><span>ArdWiki</span></div>${selected ? renderDetail(selected) : activeKind === 'quiz' ? renderQuiz() : activeKind === 'socials' ? renderSocials() : renderBrowse(visible, filtered.length)}</main></div></div>`
  bindEvents()
  bindEnhancements()
  bindFilters()
  bindQuiz()
}
function navButton(kind: string, icon: string, label: string, meta = '') { return `<button class="nav-item ${activeKind === kind ? 'active' : ''}" data-action="nav" data-kind="${kind}"><span class="nav-icon">${icon}</span><span>${label}</span>${meta ? `<small>${meta}</small>` : ''}</button>` }
function startQuiz(category = quizCategory) { quizCategory = category; quizRound = [...quizQuestions[category]].sort(() => Math.random() - 0.5).slice(0, 5); quizIndex = 0; quizScore = 0; quizAnswer = null }
async function loadGitHubRepos() { if (githubLoading || githubRepos) return; githubLoading = true; render(); try { const response = await fetch('https://api.github.com/users/circuitkidyt/repos?sort=updated&direction=desc&per_page=12'); if (!response.ok) throw new Error('GitHub request failed'); githubRepos = await response.json() as GitHubRepo[]; githubError = false } catch { githubError = true } finally { githubLoading = false; render() } }
function renderSocials() { if (!githubRepos && !githubLoading && !githubError) void loadGitHubRepos(); let repoContent = '<div class="repo-state"><strong>No public repositories yet.</strong><p>New public repositories will appear here automatically.</p></div>'; if (githubLoading) repoContent = '<div class="repo-state"><span class="loading-pulse"></span><strong>Checking GitHub</strong><p>Looking for the latest public repositories.</p></div>'; if (githubError) repoContent = '<div class="repo-state"><strong>GitHub is taking a breather.</strong><p>Repository data could not be loaded right now. The rest of ArdWiki is still available.</p><button class="retry-button" data-action="github-retry">Try again</button></div>'; if (githubRepos?.length) repoContent = `<div class="repo-grid">${githubRepos.map(renderRepo).join('')}</div>`; return `<section class="socials-page"><div class="eyebrow"><span class="eyebrow-line"></span> CIRCUITKID / CREATOR</div><h1>Keep learning,<br><em>keep building.</em></h1><p class="hero-copy">ArdWiki is a quiet reference companion for the Arduino and ESP32 community. Follow CircuitKid for the ideas behind the boards.</p><div class="social-links"><a class="social-link" href="https://github.com/circuitkidyt" target="_blank" rel="noreferrer"><span class="social-symbol">◉</span><span><strong>GitHub</strong><small>circuitkidyt</small></span><b>↗</b></a><a class="social-link" href="https://tiktok.com/@circuitkid" target="_blank" rel="noreferrer"><span class="social-symbol">♪</span><span><strong>TikTok</strong><small>@circuitkid</small></span><b>↗</b></a></div><section class="repos-section"><div class="section-heading"><div><span class="eyebrow small">LIVE FROM GITHUB</span><h2>Latest repositories</h2></div><span class="repo-source">Public repos · updates automatically</span></div>${repoContent}</section></section>` }
function renderRepo(repo: GitHubRepo) { return `<a class="repo-card" href="${repo.html_url}" target="_blank" rel="noreferrer"><div class="repo-card-top"><span>◒ PUBLIC REPOSITORY</span><b>↗</b></div><h3>${escapeHtml(repo.name)}</h3><p>${escapeHtml(repo.description || 'No description provided yet.')}</p><div class="repo-meta"><span>${repo.language ? `<i class="language-dot"></i>${escapeHtml(repo.language)}` : 'No language listed'}</span><span>★ ${repo.stargazers_count}</span><span>⑂ ${repo.forks_count}</span></div><small class="repo-updated">Updated ${new Date(repo.updated_at).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</small></a>` }
function renderQuiz() {
  if (!quizRound.length) startQuiz()
  const question = quizRound[quizIndex]
  const finished = quizIndex >= quizRound.length
  const tabs = quizNames.map((name) => '<button class="quiz-tab ' + (quizCategory === name ? 'active' : '') + '" data-action="quiz-category" data-category="' + name + '">' + name + '</button>').join('')
  const answers = question ? question.choices.map((choice, index) => { const state = quizAnswer === null ? '' : index === question.answer ? 'correct' : index === quizAnswer ? 'wrong' : 'muted'; return '<button class="answer-choice ' + state + '" data-action="quiz-answer" data-answer="' + index + '"><span>' + String.fromCharCode(65 + index) + '</span>' + escapeHtml(choice) + '</button>' }).join('') : ''
  const feedback = question && quizAnswer !== null ? '<div class="quiz-feedback ' + (quizAnswer === question.answer ? 'good' : 'bad') + '"><strong>' + (quizAnswer === question.answer ? 'Nice work.' : 'Not quite.') + '</strong><span>' + question.explanation + '</span><button data-action="quiz-next">' + (quizIndex === quizRound.length - 1 ? 'See score' : 'Next question') + ' -></button></div>' : ''
  const body = finished ? renderQuizComplete() : '<div class="quiz-card"><div class="quiz-card-top"><span>' + quizCategory.toUpperCase() + '</span><span>Question ' + (quizIndex + 1) + ' of ' + quizRound.length + '</span></div><div class="progress-track"><i style="width:' + ((quizIndex / quizRound.length) * 100) + '%"></i></div><h2>' + escapeHtml(question.prompt) + '</h2><div class="answer-grid">' + answers + '</div>' + feedback + '</div>'
  return '<section class="quiz-page"><div class="eyebrow"><span class="eyebrow-line"></span> ARDWIKI LEARNING LAB</div><div class="quiz-title-row"><div><h1>Check your <em>circuit sense.</em></h1><p class="hero-copy">Short quizzes for the moments when you want to test what stuck.</p></div><span class="quiz-best">Best score <strong>' + (quizBest[quizCategory] || 0) + '/5</strong></span></div><div class="quiz-tabs">' + tabs + '</div>' + body + '<div class="quiz-note"><span>✦</span><div><strong>Learn, then look it up</strong><p>Quiz questions link back to the same beginner-friendly reference pages used across ArdWiki.</p></div></div></section>'
}
function renderQuizComplete() { const percent = Math.round((quizScore / quizRound.length) * 100); const mark = percent >= 80 ? '✓' : '↻'; const message = percent >= 80 ? 'You have a strong handle on these ideas.' : 'A few more reps will make this feel natural.'; return '<div class="quiz-complete"><div class="complete-mark">' + mark + '</div><span class="eyebrow small">' + quizCategory.toUpperCase() + ' COMPLETE</span><h2>' + quizScore + ' out of ' + quizRound.length + '</h2><p>' + message + '</p><button class="primary-button" data-action="quiz-retry">Try another round</button></div>' }
function renderBrowse(visible: WikiItem[], resultCount: number) { const isSearch = query.length > 0; return `<section class="hero-section"><div class="eyebrow"><span class="eyebrow-line"></span> THE FRIENDLY MICROCONTROLLER REFERENCE</div><h1>Build your confidence,<br><em>one pin at a time.</em></h1><p class="hero-copy">Clear, beginner-first answers for Arduino and ESP32 programming.<br class="desktop-only"> No jargon maze. Just the thing you need, when you need it.</p><div class="search-wrap"><span class="search-icon">⌕</span><input id="search" value="${escapeHtml(query)}" placeholder="Search functions, components, or concepts..." autocomplete="off"><kbd>⌘ K</kbd></div><div class="search-meta">${isSearch ? `<strong>${resultCount}</strong> ${resultCount === 1 ? 'result' : 'results'} for <strong>“${escapeHtml(query)}”</strong>` : 'Try searching for <button data-search="map">map</button>, <button data-search="LED">LED</button>, or <button data-search="Serial">Serial</button>'}</div></section><section class="welcome-band"><div class="welcome-icon">◎</div><div><strong>New here?</strong> Start with <button data-action="open-function" data-name="pinMode()">pinMode()</button> to learn how a board talks to the real world.</div><span class="board-art"><i></i><i></i><i></i><i></i><i></i></span></section><section class="browse-section"><div class="section-heading"><div><span class="eyebrow small">${isSearch ? 'SEARCH RESULTS' : activeKind === 'home' ? 'START HERE' : activeKind.toUpperCase()}</span><h2>${isSearch ? 'Here’s what we found' : activeKind === 'home' ? 'A friendly place to look things up' : activeKind === 'functions' ? 'Functions & commands' : 'Components & modules'}</h2></div>${!isSearch ? '<div class="view-toggle"><button class="selected">▦</button><button>☷</button></div>' : ''}</div>${visible.length ? `<div class="card-grid">${visible.map(renderCard).join('')}</div>` : '<div class="empty-state"><span>⌕</span><strong>No matches yet</strong><p>Try a shorter search like “pin”, “sensor”, or “motor”.</p></div>'}</section>` }
function renderCard(item: WikiItem) { const functionItem = item.kind === 'function'; return `<article class="wiki-card ${functionItem ? 'function-card' : 'component-card'}" data-action="open-${item.kind}" data-name="${item.name}"><div class="card-top"><span class="type-label ${functionItem ? 'code-label' : 'part-label'}">${functionItem ? '</> FUNCTION' : '◈ COMPONENT'}</span><span class="card-actions"><span class="support ${supportClass(item.support)}"><i></i>${item.support}</span><button class="favorite-button ${favorites.has(item.name) ? 'saved' : ''}" data-action="favorite" data-name="${item.name}" aria-label="${favorites.has(item.name) ? 'Remove from favorites' : 'Add to favorites'}">${favorites.has(item.name) ? '★' : '☆'}</button></span></div>${!functionItem ? `<div class="component-visual ${item.visual}"><span>${visualLabel(item.visual)}</span></div>` : `<div class="code-preview"><span class="syntax-purple">${item.name.split('(')[0]}</span><span class="syntax-white">(</span><span class="syntax-orange">...</span><span class="syntax-white">);</span></div>`}<h3>${item.name}</h3><p>${item.summary}</p><div class="card-foot"><span>${item.group}</span><span class="arrow">↗</span></div></article>` }
function visualLabel(visual: string) { return ({ led: 'LED', resistor: 'Ω', knob: '◉', button: '●', buzzer: ')))', servo: '↻', ultrasonic: ')))', sensor: 'DHT', oled: 'OLED', relay: '▣', motor: 'M', stepper: '↻', driver: 'ULN', pir: 'PIR', ldr: 'LDR', joystick: '✣', lcd: 'LCD', ir: 'IR', rgb: 'RGB', breadboard: '▦' } as Record<string, string>)[visual] || 'PART' }
function renderDetail(item: WikiItem) { const functionItem = item.kind === 'function'; return `<div class="detail-view"><div class="breadcrumbs"><button data-action="home">Home</button><span>/</span><button data-action="nav" data-kind="${functionItem ? 'functions' : 'components'}">${functionItem ? 'Functions' : 'Components'}</button><span>/</span><strong>${item.name}</strong></div><button class="back-link" data-action="back">← Back to ${functionItem ? 'functions' : 'components'}</button><div class="detail-header"><div><span class="type-label ${functionItem ? 'code-label' : 'part-label'}">${functionItem ? '</> FUNCTION' : '◈ COMPONENT'}</span><h1>${item.name}</h1><p>${item.summary}</p></div><span class="support large ${supportClass(item.support)}"><i></i>Works with ${item.support}</span></div>${functionItem ? renderFunctionDetail(item) : renderComponentDetail(item)}${renderRelated(item)}</div>` }
function renderFunctionDetail(item: FunctionEntry) { return `<div class="detail-grid"><div class="detail-main"><section class="info-block"><h2>Syntax</h2><div class="code-block"><div class="code-toolbar"><span>arduino</span><button data-action="copy" data-code="${escapeHtml(item.example)}">□ Copy code</button></div><pre><code>${highlight(item.syntax)}</code></pre></div></section><section class="info-block"><h2>Parameters</h2><p>${item.parameters}</p></section><section class="info-block"><h2>Return value</h2><p>${item.returns}</p></section><section class="info-block"><h2>Example</h2><div class="code-block"><div class="code-toolbar"><span>arduino</span><button data-action="copy" data-code="${escapeHtml(item.example)}">□ Copy code</button></div><pre><code>${highlight(item.example)}</code></pre></div><div class="behavior"><strong>What happens?</strong><span>${item.behavior}</span></div></section><button class="learn-link" data-action="quiz-link" data-category="Functions">Test this idea in the Functions quiz →</button></div><aside class="detail-aside"><div class="aside-card"><span class="aside-kicker">GOOD TO KNOW</span><strong>Beginner tip</strong><p>${item.tips}</p></div><div class="aside-card warning"><span class="aside-kicker">WATCH OUT</span><strong>Common mistake</strong><p>${item.mistakes}</p></div><div class="aside-card board-compat"><span class="aside-kicker">COMPATIBILITY</span><strong>Supported boards</strong><div class="compat-row"><span class="board-chip arduino">A</span> Arduino ${item.support !== 'ESP32' ? '<b>✓</b>' : ''}</div><div class="compat-row"><span class="board-chip esp">E</span> ESP32 ${item.support !== 'Arduino' ? '<b>✓</b>' : ''}</div></div></aside></div>` }
function renderComponentFunction(entry: ComponentFunction, index: number) { return `<details class="component-function" ${index === 0 ? 'open' : ''}><summary><span><strong>${entry.name}</strong><small>${entry.explanation}</small></span><b>+</b></summary><div class="component-function-body"><div><span class="function-label">Syntax</span><code>${highlight(entry.syntax)}</code></div><div><span class="function-label">Example</span><pre><code>${highlight(entry.example)}</code></pre></div></div></details>` }
function renderComponentDetail(item: ComponentEntry) { const example = componentExamples[item.name] || { code: `const int signalPin = 2;\n\nvoid setup() {\n  pinMode(signalPin, INPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  Serial.println(digitalRead(signalPin));\n  delay(200);\n}`, explanation: 'This starter pattern powers the component, reads its signal pin, and prints a simple value so you can see what it is doing.' }; return `<div class="component-detail-grid"><div><div class="detail-component-visual ${item.visual}"><span>${visualLabel(item.visual)}</span></div><section class="info-block"><h2>What it is</h2><p>${item.whatItDoes}</p></section><section class="info-block"><h2>Pins & connection</h2><p><strong>Pins:</strong> ${item.pins}</p><p><strong>Common connection:</strong> ${item.connection}</p></section><section class="info-block component-functions"><div class="component-functions-heading"><div><h2>Common functions</h2><p>Open a function to see its syntax and a component-sized example.</p></div><span>${item.functions?.length || 0} essentials</span></div>${(item.functions || []).map(renderComponentFunction).join('')}</section><section class="info-block"><h2>See it in code</h2><div class="code-block"><div class="code-toolbar"><span>arduino / esp32</span><button data-action="copy" data-code="${escapeHtml(example.code)}">□ Copy code</button></div><pre><code>${highlight(example.code)}</code></pre></div><div class="behavior"><strong>Component focus</strong><span>${example.explanation}</span></div></section><button class="learn-link" data-action="quiz-link" data-category="Components">Test this component in the Components quiz →</button></div><aside class="detail-aside"><div class="aside-card"><span class="aside-kicker">IMPORTANT SPECS</span><p>${item.specs}</p></div><div class="aside-card"><span class="aside-kicker">BEGINNER TIP</span><p>${item.tips}</p></div><div class="aside-card warning"><span class="aside-kicker">COMMON MISTAKE</span><p>${item.mistakes}</p></div><div class="aside-card board-compat"><span class="aside-kicker">COMPATIBILITY</span><strong>Works with ${item.support}</strong></div></aside></div>` }
function renderRelated(item: WikiItem) { const related = allItems.filter((candidate) => candidate !== item && candidate.group === item.group).slice(0, 4); return related.length ? `<section class="related-section"><div class="eyebrow small">KEEP EXPLORING</div><h2>Related reference</h2><div class="related-grid">${related.map((candidate) => `<button class="related-card" data-action="open-${candidate.kind}" data-name="${candidate.name}"><span>${candidate.kind === 'function' ? '</>' : '◈'}</span><strong>${candidate.name}</strong><small>${candidate.summary}</small></button>`).join('')}</div></section>` : '' }
function highlight(code: string) { return escapeHtml(code).replace(/(pinMode|digitalWrite|digitalRead|analogRead|analogWrite|delay|millis|map|constrain|Serial|if|else|for|while|switch|case)/g, '<span class="syntax-purple">$1</span>').replace(/(HIGH|LOW|INPUT|OUTPUT|A0|int|unsigned long)/g, '<span class="syntax-blue">$1</span>').replace(/(&quot;.*?&quot;)/g, '<span class="syntax-green">$1</span>') }
function escapeHtml(text: string) { return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;') }
function bindEvents() { document.querySelectorAll<HTMLElement>('[data-action="nav"]').forEach((el) => el.onclick = () => { activeKind = el.dataset.kind as typeof activeKind; selected = null; query = ''; render() }); document.querySelectorAll<HTMLElement>('[data-action^="open-"]').forEach((el) => el.onclick = (event) => { event.preventDefault(); selected = allItems.find((item) => item.name === el.dataset.name) || null; render() }); document.querySelectorAll<HTMLElement>('[data-search]').forEach((el) => el.onclick = () => { query = el.dataset.search || ''; selected = null; render(); setTimeout(() => document.querySelector<HTMLInputElement>('#search')?.focus()) }); document.querySelectorAll<HTMLElement>('[data-action="theme"]').forEach((el) => el.onclick = () => { lightMode = !lightMode; render() }); document.querySelectorAll<HTMLElement>('[data-action="back"], [data-action="home"]').forEach((el) => el.onclick = (event) => { event.preventDefault(); selected = null; activeKind = el.dataset.action === 'home' ? 'home' : activeKind; render() }); document.querySelectorAll<HTMLElement>('[data-action="copy"]').forEach((el) => el.onclick = async () => { await navigator.clipboard?.writeText(el.dataset.code || ''); el.textContent = '✓ Copied'; setTimeout(() => { el.textContent = '□ Copy code' }, 1300) }); document.querySelectorAll<HTMLElement>('[data-action="open-menu"]').forEach((el) => el.onclick = () => document.querySelector('.sidebar')?.classList.add('open')); document.querySelectorAll<HTMLElement>('[data-action="close-menu"]').forEach((el) => el.onclick = () => document.querySelector('.sidebar')?.classList.remove('open')); const search = document.querySelector<HTMLInputElement>('#search'); search?.addEventListener('input', () => { query = search.value; selected = null; render(); document.querySelector<HTMLInputElement>('#search')?.focus(); const input = document.querySelector<HTMLInputElement>('#search'); input?.setSelectionRange(query.length, query.length) }) }
function bindEnhancements() { document.querySelectorAll<HTMLElement>('[data-action="favorite"]').forEach((el) => el.onclick = (event) => { event.stopPropagation(); const name = el.dataset.name || ''; favorites.has(name) ? favorites.delete(name) : favorites.add(name); localStorage.setItem('ardwiki-favorites', JSON.stringify([...favorites])); render() }); document.querySelectorAll<HTMLElement>('[data-action="favorites"]').forEach((el) => el.onclick = () => { showFavorites = true; selected = null; query = ''; render() }); document.querySelectorAll<HTMLElement>('[data-action="open-recent"]').forEach((el) => el.onclick = () => { showFavorites = false; selected = allItems.find((item) => item.name === el.dataset.name) || null; render() }) }
function bindFilters() { const meta = document.querySelector('.search-meta'); if (!meta) return; const groups = [...new Set(allItems.map((item) => item.group))].sort(); const filters = document.createElement('div'); filters.className = 'filter-bar'; filters.innerHTML = `<span>Filter by</span><select id="board-filter" aria-label="Filter by board"><option>All boards</option><option>Arduino</option><option>ESP32</option></select><select id="category-filter" aria-label="Filter by category"><option>All categories</option>${groups.map((group) => `<option>${group}</option>`).join('')}</select>`; meta.after(filters); const board = filters.querySelector<HTMLSelectElement>('#board-filter'); const category = filters.querySelector<HTMLSelectElement>('#category-filter'); if (!board || !category) return; if (boardFilter !== 'All') board.value = boardFilter; if (categoryFilter !== 'All') category.value = categoryFilter; board.addEventListener('change', () => { boardFilter = board.value === 'All boards' ? 'All' : board.value as Support; render() }); category.addEventListener('change', () => { categoryFilter = category.value === 'All categories' ? 'All' : category.value; render() }) }
function bindQuiz() { document.querySelectorAll<HTMLElement>('[data-action="quiz-category"]').forEach((el) => el.onclick = () => { startQuiz(el.dataset.category || 'Beginner'); render() }); document.querySelectorAll<HTMLElement>('[data-action="quiz-answer"]').forEach((el) => el.onclick = () => { if (quizAnswer !== null) return; quizAnswer = Number(el.dataset.answer); if (quizAnswer === quizRound[quizIndex].answer) quizScore += 1; render() }); document.querySelectorAll<HTMLElement>('[data-action="quiz-next"]').forEach((el) => el.onclick = () => { quizIndex += 1; quizAnswer = null; if (quizIndex >= quizRound.length) { quizBest[quizCategory] = Math.max(quizBest[quizCategory] || 0, quizScore); localStorage.setItem('circuitkid-quiz-best', JSON.stringify(quizBest)) } render() }); document.querySelectorAll<HTMLElement>('[data-action="quiz-retry"]').forEach((el) => el.onclick = () => { startQuiz(); render() }); document.querySelectorAll<HTMLElement>('[data-action="quiz-link"]').forEach((el) => el.onclick = () => { selected = null; activeKind = 'quiz'; startQuiz(el.dataset.category || 'Beginner'); render() }); document.querySelectorAll<HTMLElement>('[data-action="github-retry"]').forEach((el) => el.onclick = () => { githubError = false; githubRepos = null; void loadGitHubRepos() }); document.querySelectorAll<HTMLElement>('[data-action="random"]').forEach((el) => el.onclick = () => { selected = allItems[Math.floor(Math.random() * allItems.length)]; activeKind = selected.kind === 'function' ? 'functions' : 'components'; render() }) }
document.addEventListener('keydown', (event) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); document.querySelector<HTMLInputElement>('#search')?.focus() } })
render()
